'use strict';
// Isolated, in-memory technical-mode example. No service control or backend enforcement.
const technicalLabels={off:['Технический режим выключен','Technical mode is off'],pending:['Команда принята · остановка не подтверждена','Command accepted · shutdown unconfirmed'],partial:['Остановка подтверждена не полностью','Shutdown partially confirmed'],unknown:['Результат команды неизвестен','Command outcome unknown'],active:['Технический режим включён','Technical mode is on'],failed:['Команда отклонена · режим не включён','Command rejected · mode not enabled'],restored:['Технический режим выключен','Technical mode is off']};
function newTechnical(){return {phase:'off',reason:'',review:null,proof:null,revision:1,operation:null,outcome:'active',auth:true,error:null,events:[],preview:false,editing:false,returnRoute:'overview',recovery:false};}
let technical=newTechnical();
const technicalLocked=()=>['pending','partial','unknown','active'].includes(technical.phase);
function technicalAccess(){const g=account?.logged?management.assignments[actor().id]:null;return {read:!!account?.logged&&['ownerA','ownerB','lead','ops','audit'].includes(state.role),activate:!!account?.logged&&['ownerA','ownerB','lead'].includes(state.role)&&!management.revoked&&g?.status==='active'&&(!g.expires||g.expires>management.clock)&&g.environment==='paper'&&g.venue==='both'&&g.rights.includes('emergency.activate')};}
const technicalButton=(ru,en,a,attrs='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-technical="${a}" ${attrs}>${pl(ru,en)}</button>`;
const technicalDigest=()=>JSON.stringify([actor().id,technical.reason.trim(),technical.revision,management.assignments[actor().id]?.revision]);
function technicalError(ru,en){technical.error=[ru,en];return false;}
function technicalChange(value){if(!technicalAccess().activate||technicalLocked())return false;technical.reason=String(value).slice(0,500);technical.revision++;technical.review=null;technical.proof=null;technical.error=null;return true;}
function technicalReview(){technical.proof=null;if(!technicalAccess().activate||technicalLocked()||technical.reason.trim().length<8)return technicalError('Нужны причина от 8 символов и право включить ограничение для всей среды.','A reason of at least 8 characters and permission covering the whole environment are required.');technical.review=technicalDigest();technical.error=null;return true;}
function technicalProof(){technical.proof=null;if(!technicalAccess().activate||!technical.review||technical.review!==technicalDigest()||!technical.auth||!account.protected)return technicalError('Проверка личности не завершена или данные изменились. Вернитесь к проверке последствий.','Identity verification did not complete or data changed. Review effects again.');technical.proof=technicalDigest();return true;}
function technicalSubmit(){if(!technicalAccess().activate||technicalLocked()||!technical.review||technical.review!==technicalDigest()||technical.proof!==technicalDigest())return technicalError('Команда не отправлена: заново проверьте последствия и личность.','Command not sent: review effects and verify identity again.');technical.operation={id:'TECH-DEMO-'+(technical.events.length+1),actor:actor().id,reason:technical.reason.trim(),revision:technical.revision};technical.phase='pending';technical.editing=false;technical.recovery=false;technical.proof=null;technical.review=null;technical.events.push({actor:actor().id,label:['Запрошено отключение всей среды','Entire environment shutdown requested']});return true;}
function technicalObserve(){if(!technicalAccess().read||!technicalLocked())return false;const next=technical.outcome;if(!['pending','partial','unknown','active','failed'].includes(next))return false;if(technical.operation.confirmedAny&&next==='failed')return false;if(['active','partial'].includes(next))technical.operation.confirmedAny=true;technical.phase=next;technical.events.push({actor:actor().id,label:technicalLabels[next]});return true;}
function technicalStartRecovery(){if(!technicalAccess().read||technical.phase!=='active')return technicalError('Сначала подтвердите состояние всех компонентов. Неизвестный результат нельзя считать остановкой.','Confirm every component first. An unknown outcome is not a confirmed shutdown.');if(!technical.recovery){if(['waiting','approved','unknown'].includes(emergency.status))return technicalError('Сначала завершите уже открытый запрос восстановления. Он не будет перезаписан.','Finish the existing recovery request first. It will not be overwritten.');emergency=newEmergency();emergency.scope='technical';emergency.technicalOperation=technical.operation.id;emergency.returnRoute='technical';technical.recovery=true;}navigate('emergency');return true;}
function technicalRouteAllowed(route){return !technicalLocked()||['entry','technical','profile','incidents','incident','reconciliation','reconciliationItem','emergency'].includes(route);}
function technicalNav(){return technicalAccess().read?technicalButton('Технический режим','Technical mode','open',state.route==='technical'?'aria-current="page"':'').replace('class="btn"','class="sub '+(state.route==='technical'?'selected':'')+'"'):'';}
function technicalAction(a){if(!account?.logged)return false;if(a==='open'){if(!technicalAccess().read)return false;technical.returnRoute=state.route==='technical'?technical.returnRoute:state.route;navigate('technical');return true;}if(!technicalAccess().read)return false;technical.error=null;let result=true;if(a==='begin'){if(!technicalAccess().activate||technicalLocked())return false;technical.editing=true;}else if(a==='review')result=technicalReview();else if(a==='proof')result=technicalProof();else if(a==='submit')result=technicalSubmit();else if(a==='observe')result=technicalObserve();else if(a==='recover'){result=technicalStartRecovery();if(result)return true;}else if(a==='retry-recovery'){if(emergency.status!=='rejected'||!technicalAccess().read)return false;technical.recovery=false;result=technicalStartRecovery();if(result)return true;}else if(a==='existing'){navigate('emergency');return true;}else if(a==='cancel'){technical.review=null;technical.proof=null;technical.editing=false;}else if(a==='preview')technical.preview=!technical.preview;else if(a==='back'){navigate(technical.returnRoute);return true;}else return false;render();if(['begin','review','proof','submit','observe','cancel'].includes(a)){const target=document.querySelector('.technical-flow h2')||document.querySelector('.technical-status');target?.setAttribute('tabindex','-1');target?.focus({preventScroll:false});}return result;}
function technicalEffects(){return `<ul class="trading-checks">${[['Приложение и публичный API','App and public API','Доступ будет закрыт','Access will be closed'],['Торговля и деньги через Shadow','Trading and money through Shadow','Новые действия будут запрещены','New actions will be blocked'],['Продуктовые фоновые задания','Product background tasks','Все задания будут остановлены','All tasks will be stopped']].map(([a,b,c,d],i)=>`<li><strong>${pl(a,b)}</strong><span>${technicalLocked()?(technical.phase==='active'||technical.phase==='partial'&&i<2?pl('Подтверждено','Confirmed'):pl('Не подтверждено','Unconfirmed')):pl(c,d)}</span></li>`).join('')}</ul>`;}
function technicalPage(){
 if(!technicalAccess().read)return heading(pl('Работа временно ограничена','Work temporarily restricted'))+`<p>${pl('Технический режим ограничивает работу. Обратитесь к владельцу; ваш профиль остаётся доступен.','Technical mode restricts work. Contact an owner; your profile remains available.')}</p>`+button(t('profile'),'profile');
 const x=technical,w=technicalAccess().activate,locked=technicalLocked();
 const hints={off:['Технический режим не ограничивает доступ к сервису.','Technical mode is not restricting access to the service.'],restored:['Отключение режима подтверждено. Другие ограничения сохранены; старые заявки не отправляются заново.','Mode removal is confirmed. Other restrictions remain; old requests are not replayed.'],active:['Приложение и публичный API закрыты, новые торговые и денежные действия запрещены, продуктовые задания остановлены.','The app and public API are closed, new trading and money actions are blocked, and product tasks are stopped.'],pending:['Команда принята. Теперь проверьте, подтвердили ли компоненты остановку.','Command accepted. Now check whether the components confirmed shutdown.'],partial:['Часть компонентов остановлена. Не включайте режим повторно — обновите состояние этой команды.','Some components have stopped. Do not enable the mode again; refresh this command’s status.'],unknown:['Ответ системы пока неизвестен. Повторная отправка заблокирована; проверьте текущую команду.','The system outcome is unknown. Resubmission is blocked; check the current command.'],failed:['Система отклонила команду до остановки. Можно заново проверить причину и попробовать включение.','The system rejected the command before shutdown. Review the reason and try enabling it again.']};
 let action='';
 if(x.phase==='active')action=technicalButton('Выключить технический режим','Turn off technical mode','recover','',true)+`<p>${pl('Далее: проверка готовности и два независимых подтверждения. Одного нажатия недостаточно.','Next: readiness checks and two independent approvals. This button alone does not turn the mode off.')}</p>`;
 else if(locked)action=technicalButton('Проверить отключение сервиса','Check service shutdown','observe','',true)+`<p>${pl('Режим можно выключить после подтверждения остановки всех компонентов. В этом демо кнопка получает подготовленный ответ системы.','You can turn the mode off once all components confirm shutdown. In this demo, the button retrieves a prepared system response.')}</p>`;
 else if(w&&!x.editing)action=technicalButton('Включить технический режим','Turn on technical mode','begin','',true)+`<p>${pl('Сначала укажите причину и подтвердите личность. Второй сотрудник для включения не нужен.','First provide a reason and verify your identity. Enabling does not require a second employee.')}</p>`;
 else if(!w)action=`<p>${pl('Только просмотр. Включить режим может владелец или руководитель с правом на всю среду.','Read only. An owner or lead with environment-wide permission can enable the mode.')}</p>`;
 const step=x.review?(x.proof===technicalDigest()?3:2):1;
 const form=!locked&&w&&x.editing?`<section class="panel technical-flow"><h2>${pl('Включение технического режима','Turn on technical mode')}</h2><p class="muted">${pl('Шаг','Step')} ${step} ${pl('из 3','of 3')} · ${pl('Причина → личность → включение','Reason → identity → enable')}</p>${!x.review?`<label for="technical-reason">${pl('Почему нужно закрыть сервис?','Why must the service be closed?')}</label><textarea id="technical-reason" maxlength="500" rows="3">${escape(x.reason)}</textarea><p class="muted">${pl('Опишите проблему: 8–500 символов. Запись попадёт в журнал; не указывайте секреты.','Describe the issue in 8–500 characters. It will be logged; do not include secrets.')}</p>${technicalButton('Далее: подтвердить личность','Next: verify identity','review','',true)}`:`<p><strong>${pl('Причина','Reason')}:</strong> ${escape(x.reason)}</p><p>${pl('Будет закрыта вся среда Shadow: Polymarket и Limitless. Аварийная админка продолжит работать.','The entire Shadow environment will close: Polymarket and Limitless. Emergency administration will remain available.')}</p>${x.proof===technicalDigest()?`<p class="badge good">${pl('Личность подтверждена · учебная проверка','Identity verified · synthetic check')}</p><p>${pl('После нажатия ниже команда будет отправлена. Затем нужно проверить подтверждение остановки.','The button below submits the command. Then check shutdown confirmation.')}</p>${technicalButton('Включить технический режим','Turn on technical mode','submit','',true)}`:technicalButton('Подтвердить личность · демо','Verify identity · demo','proof','',true)}`}${technicalButton('Отменить включение','Cancel enabling','cancel')}</section>`:'';
 return heading(pl('Технический режим','Technical mode'),pl('Отключение и восстановление пользовательской части Shadow','Shut down and restore the Shadow user service'))+`<section class="panel technical-status" aria-live="polite"><span class="badge ${locked?'warn':'good'}">${pl(...technicalLabels[x.phase])}</span><p>${pl(...hints[x.phase])}</p>${action}</section>${x.error?`<p class="account-error" role="alert">${pl(...x.error)}</p>${['waiting','approved','unknown'].includes(emergency.status)?technicalButton('Открыть текущий запрос','Open current request','existing'):''}`:''}${form}<div class="support-layout"><section class="panel"><h2>${locked?pl('Подтверждение остановки','Shutdown confirmation'):pl('Что отключает режим','What the mode shuts down')}</h2>${technicalEffects()}<p class="muted">${pl('Вся среда: Polymarket и Limitless. Отдельную площадку здесь выбрать нельзя.','Entire environment: Polymarket and Limitless. A single venue cannot be selected here.')}</p></section><section class="panel"><h2>${pl('Что остаётся доступно','What stays available')}</h2><p>${pl('Аварийная админка, наблюдение, журнал, инциденты, безопасная сверка и восстановление.','Emergency administration, monitoring, audit, incidents, safe reconciliation and recovery.')}</p><details><summary>${pl('Что значит безопасная сверка?','What is safe reconciliation?')}</summary><p>${pl('Проверка результатов без сделок, переводов и повторных заявок. Уже отправленные операции могут завершиться; прямые действия вне Shadow не блокируются.','Checking results without trades, transfers or resubmissions. Submitted operations may complete; direct actions outside Shadow are not blocked.')}</p></details>${technicalButton(x.preview?'Скрыть экран пользователя':'Что увидит пользователь?',x.preview?'Hide user screen':'What will users see?','preview')}${x.preview?`<h3>${pl('Сервис временно недоступен','Service temporarily unavailable')}</h3><p>${pl('Мы восстанавливаем работу. Повторно отправлять операции не нужно.','We are restoring service. Do not resubmit operations.')}</p>`:''}</section></div>${x.operation?`<details class="panel"><summary>${pl('Команда и причина отключения','Command and shutdown reason')} · ${x.operation.id}</summary><p>${x.operation.actor} · ${escape(x.operation.reason)}</p></details>`:''}<details class="panel"><summary>${pl('Журнал действий','Action history')} · ${x.events.length}</summary>${x.events.map(e=>`<p>${e.actor} · ${pl(...e.label)}</p>`).join('')||pl('Действий ещё нет','No actions yet')}</details><details class="panel"><summary>${pl('Демо: проверить ошибки и неполную остановку','Demo: test errors and partial shutdown')}</summary>${feedbackSelect('technical-outcome',pl('Следующий ответ системы','Next system response'),Object.entries(technicalLabels).filter(([k])=>['pending','partial','unknown','active','failed'].includes(k)).map(([k,v])=>[k,pl(...v)]),x.outcome)}<p>${pl('Измените ответ и нажмите «Проверить отключение сервиса». Обычный пример уже настроен на успешную остановку.','Change the response and click “Check service shutdown”. The normal example already uses a successful shutdown response.')}</p></details>`;
}
function technicalEmergencyNav(){return technicalAccess().read?technicalNav()+button(t('incidents'),'incidents')+button(t('reconciliation'),'reconciliation')+eb('Аварийное восстановление','Emergency recovery','open')+button(t('profile'),'profile'):button(t('profile'),'profile');}
const technicalBaseEmergencyAction=emergencyAction;
emergencyAction=function(a){const linked=technical.recovery&&emergency.technicalOperation===technical.operation?.id;if(linked&&a==='restart')return false;const result=technicalBaseEmergencyAction(a);if(result&&linked&&emergency.scope==='technical'&&emergency.status==='applied'&&technical.phase!=='restored'){technical.phase='restored';technical.events.push({actor:actor().id,label:['Снятие технического режима подтверждено','Technical mode removal confirmed']});render();}return result;};
const technicalBaseEmergencyChange=emergencyChange;
emergencyChange=function(k,v){if(technical.recovery&&emergency.technicalOperation===technical.operation?.id&&k==='scope')return false;return technicalBaseEmergencyChange(k,v);};
const technicalBaseEmergencyPage=emergencyPage;
emergencyPage=function(){
 if(!technical.recovery||emergency.technicalOperation!==technical.operation?.id)return technicalBaseEmergencyPage();
 const x=emergency,w=emergencyAccess().confirm,valid=emergencyValid(),signed=valid.some(p=>p.id===actor().id);
 let title,body,actions='';
 if(x.status==='applied'){title=pl('Технический режим выключен','Technical mode is off');body=pl('Система подтвердила снятие режима. Другие ограничения сохранены. Сделки и переводы автоматически не запускаются.','The system confirmed mode removal. Other restrictions remain. Trades and transfers do not restart automatically.');actions=technicalButton('К техническому режиму','Back to technical mode','open','',true);}
 else if(x.status==='unknown'){title=pl('Проверяем результат выключения','Checking the turn-off result');body=pl('Режим считается включённым, пока нет подтверждения. Повторная команда запрещена.','The mode remains on until confirmed. Do not resend the command.');actions=w?eb('Проверить результат выключения','Check turn-off result','reconcile','',true):'';}
 else if(x.status==='rejected'){title=pl('Выключение отклонено','Turn-off rejected');body=pl('Технический режим остаётся включённым. Для новой попытки заново подготовьте запрос и подтверждения.','Technical mode remains on. Start a new request and collect new approvals to try again.');actions=technicalButton('Подготовить новый запрос','Prepare new request','retry-recovery','',true);}
 else if(!w||signed&&x.status==='waiting'){title=pl('Нужно подтверждение другого владельца','Another owner must approve');body=signed?pl('Ваше подтверждение сохранено. Второй владелец должен самостоятельно войти, проверить ту же версию и подтвердить её.','Your approval is saved. The second owner must sign in independently, review the same revision and approve it.'):pl('В вашем назначении нет права выключать режим. В этом демо нужны подтверждения двух владельцев.','Your assignment cannot turn off the mode. This demo requires approvals from both owners.');actions=eb('Выйти и передать второму владельцу','Sign out and hand over to another owner','handoff','',true);}
 else if(x.status==='approved'){title=pl('Два подтверждения получены — можно выключить','Two approvals received — ready to turn off');body=pl('Проверьте состав подтверждений и отправьте согласованную команду. До этого режим остаётся включённым.','Review the approvals and send the approved command. Until then, the mode remains on.');actions=eb('Выключить технический режим','Turn off technical mode','apply','',true);}
 else if(!emergencyReady()){title=pl('1. Подготовьте выключение','1. Prepare to turn off');body=pl('Укажите, почему сервис можно открыть. Затем получите результаты проверки готовности.','Explain why the service can reopen. Then obtain readiness check results.');actions=`<label for="emergency-reason">${pl('Что исправлено и проверено?','What has been fixed and checked?')}</label><textarea id="emergency-reason" rows="3" maxlength="1000">${escape(x.reason)}</textarea><p class="muted">${pl('Минимум 8 символов. Изменение причины отменяет прежние подтверждения.','At least 8 characters. Changing the reason clears previous approvals.')}</p>${eb('Проверить готовность к выключению · демо','Check readiness to turn off · demo','evidence',x.reason.trim().length<8?'disabled':'',true)}`;}
 else{title=pl(valid.length?'2. Подтверждение второго владельца':'2. Подтверждение первого владельца',valid.length?'2. Second owner approval':'2. First owner approval');body=pl('Причина устранена, компоненты проверены, исходные операции сверены. Подтвердите личность и согласуйте эту версию.','The cause is resolved, components checked and original operations reconciled. Verify your identity and approve this revision.');actions=x.proof===emergencyDigest()?eb('Подтвердить выключение режима','Approve turning off the mode','approve','',true):eb('Подтвердить личность · демо','Verify identity · demo','proof','',true);}
 return heading(pl('Выключить технический режим','Turn off technical mode'),pl('Подготовка → два подтверждения → выключение','Prepare → two approvals → turn off'),technicalButton('К состоянию режима','Back to mode status','open'))+`<section class="panel technical-flow"><span class="badge ${x.status==='applied'?'good':'warn'}">${pl(x.status==='applied'?'Выключен':'Пока включён',x.status==='applied'?'Off':'Still on')}</span><h2>${title}</h2><p>${body}</p>${x.notice?`<p role="status">${pl(...x.notice)}</p>`:''}<div class="technical-next">${actions}</div></section><div class="support-layout"><section class="panel"><h2>${pl('Согласованное действие','Action to approve')}</h2><p>${pl('Снять технический режим для всей среды Shadow: Polymarket и Limitless. Другие запреты сохраняются; старые заявки не повторяются.','Remove technical mode for the entire Shadow environment: Polymarket and Limitless. Other restrictions remain; old requests are not replayed.')}</p><p><strong>${pl('Основание','Reason')}:</strong> ${escape(x.reason)||pl('Ещё не указано','Not provided yet')}</p><p>${pl('Версия запроса','Request revision')}: ${x.version} · ${technical.operation.id}</p><p>${pl('Проверка готовности','Readiness check')}: ${x.evidence==='ready'?pl('пройдена · учебные результаты','passed · synthetic results'):pl('ожидает','pending')}</p></section><section class="panel"><h2>${pl('Кто подтверждает','Who approves')}</h2><p>${pl('Нужны владелец и другой уполномоченный сотрудник. В этом демо право выдано двум владельцам. Один человек не может подтвердить дважды.','An owner and another authorized employee are required. In this demo, both owners have that permission. One person cannot approve twice.')}</p><ol>${[0,1].map(i=>`<li>${valid[i]?`${valid[i].id} · ${pl('подтверждено','approved')}`:pl('Ожидает подтверждения','Awaiting approval')}</li>`).join('')}</ol>${w&&['draft','waiting','approved'].includes(x.status)?eb('Отклонить выключение','Reject turn-off','reject'):''}</section></div><details class="panel"><summary>${pl('Демо: результат выключения','Demo: turn-off result')}</summary>${feedbackSelect('emergency-outcome',pl('Ответ системы','System response'),[['success',pl('Подтверждено','Confirmed')],['unknown',pl('Результат неизвестен','Unknown outcome')],['failure',pl('Не началось','Did not start')]],x.outcome)}</details>`;
};
document.addEventListener('click',e=>{const n=e.target.closest('[data-technical]');if(n&&!n.disabled)technicalAction(n.dataset.technical);});
document.addEventListener('input',e=>{if(e.target.id!=='technical-reason')return;const p=e.target.selectionStart;technicalChange(e.target.value);render();const n=document.querySelector('#technical-reason');n?.focus();n?.setSelectionRange(p,p);});
document.addEventListener('change',e=>{if(e.target.id==='technical-outcome'&&technicalAccess().read)technical.outcome=e.target.value;});
